{
  "imports": [
    "from decimal import Decimal",
    "import pytest",
    "from ledger.shipping import shipping_cost"
  ],
  "tests": [
    {
      "name": "test_example_from_task",
      "intent": "the example given in the task: 2.5 kg costs 9.00",
      "code": "# intent: the example given in the task: 2.5 kg costs 9.00\ndef test_example_from_task():\n    assert shipping_cost(Decimal(\"2.5\")) == Decimal(\"9.00\")\n"
    },
    {
      "name": "test_whole_kilograms",
      "intent": "whole kilograms are charged exactly for each started kilogram",
      "code": "# intent: whole kilograms are charged exactly for each started kilogram\ndef test_whole_kilograms():\n    assert shipping_cost(Decimal(\"3.0\")) == Decimal(\"9.00\")\n"
    },
    {
      "name": "test_just_above_whole_kilogram",
      "intent": "any fraction above a whole kilogram counts as a started kilogram",
      "code": "# intent: any fraction above a whole kilogram counts as a started kilogram\ndef test_just_above_whole_kilogram():\n    assert shipping_cost(Decimal(\"3.01\")) == Decimal(\"11.00\")\n"
    },
    {
      "name": "test_exactly_one_kilogram",
      "intent": "exactly one kilogram costs only the first kilogram price",
      "code": "# intent: exactly one kilogram costs only the first kilogram price\ndef test_exactly_one_kilogram():\n    assert shipping_cost(Decimal(\"1.0\")) == Decimal(\"5.00\")\n"
    },
    {
      "name": "test_less_than_one_kilogram",
      "intent": "parcels lighter than one kilogram still pay the first kilogram price",
      "code": "# intent: parcels lighter than one kilogram still pay the first kilogram price\ndef test_less_than_one_kilogram():\n    assert shipping_cost(Decimal(\"0.5\")) == Decimal(\"5.00\")\n"
    },
    {
      "name": "test_zero_weight_rejected",
      "intent": "zero weight is invalid and raises ValueError",
      "code": "# intent: zero weight is invalid and raises ValueError\ndef test_zero_weight_rejected():\n    with pytest.raises(ValueError):\n        shipping_cost(Decimal(\"0\"))\n"
    }
  ]
}
